import os
import logging
from taf.transport.ssh import ssh
from ._xml_helper import XML


class bb2(object):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def __init__(self):
        self.csn = ssh()
        self._xml = XML()

    def do_preattach_configuration(self,
                                   bb2_swconfig_path='/var/preserve/swconfig.txt',
                                   bb2_connection="BB2",
                                   asia_connection="ASIA",
                                   radio_connections=None):
        if not radio_connections:
            radio_connections = ["RADIO_N0", "RADIO_N2"]
        self._configure_ASIA(connection=asia_connection)
        self._configure_radio_attenuation(radio_connections)
        self._set_BB2_flags(bb2_swconfig_path, connection=bb2_connection)

    def _configure_ASIA(self, connection="ASIA"):
        logging.info("Configuring asia for attach purposes")
        asia_10mhz_synchro_command = "ddal -s ddal_clk_io_set_single_ended_clk_out1_to 1 DDAL_OUTPUT_CLK_SRC_10M_INT"
        self.csn.send_command(asia_10mhz_synchro_command, connection=connection)
        self.csn.read_output(connection=connection)
        logging.info("The output of this should be 0x2 (sync signal is on)")
        asia_check_synchro_command = "cat /sys/class/clk/picasso/regs/clk_single_out1_select_rw"
        self.csn.send_command(asia_check_synchro_command, connection=connection)
        self.csn.read_output(connection=connection)

    def _configure_radio_attenuation(self, radio_connections):
        logging.info("Configuring radio attenuation")
        for con in radio_connections:
            self._set_attenuation(con)

    def _set_attenuation(self, connection):
        set_attenuation_command = "/sbin/devmem 0xa000b088 32 0x00000020; /sbin/devmem 0xa000b08c 32 0x00000020"
        get_attenuation_command = "/sbin/devmem 0xa000b088 32; /sbin/devmem 0xa000b08c 32"
        self.csn.send_command(set_attenuation_command, connection=connection)
        self.csn.send_command(get_attenuation_command, connection=connection)
        self.csn.read_output(connection=connection)

    def _set_BB2_flags(self, bb2_swconfig_path, connection="BB2"):
        swconfig_path = "resources/swconfig.txt"
        self.csn.upload_file(local_path=swconfig_path,
                             remote_path=bb2_swconfig_path,
                             connection=connection)

    def check_port_on_bb2(self, port, alias):
        self.csn.send_command("netstat -plnt | grep {port}".format(port=port), connection=alias)
        stdout = self.csn.read_output(connection=alias)
        assert str(port) in stdout, "{} should contain {}".format(stdout, port)

    def increase_logging_on_bb2(self, bb2_local_alias):
        logging.info("Increase logging level on BB2")
        self._patch_up_file(bb2_local_alias)
        self._patch_mix_file(bb2_local_alias)

    def _patch_up_file(self, bb2_local_alias):
        download_path_up = '/tmp/CCSEarlyConfig_up.xml'
        self.csn.download_file("/opt/nokia/SS_RCPCCSRT/CCSEarlyConfig_up.xml",
                               download_path_up, connection=bb2_local_alias)
        xml_to_edit = self._xml.parse_xml(download_path_up)
        set_element = self._xml.set_element_text(xml_to_edit, text='4',
                                                 xpath='.//tag[@name="ccs.service.aasyslog.outputmode"]')
        set_element = self._xml.set_element_text(xml_to_edit, text='1',
                                                 xpath='.//tag[@name="ccs.service.aasyslog.outputlevel"]')
        set_element = self._xml.set_element_text(xml_to_edit, text='1',
                                                 xpath='.//tag[@name="ccs.service.aasyslog.inputlevel"]')
        self._xml.save_xml(set_element, download_path_up)
        self.csn.upload_file(download_path_up,
                             "/opt/nokia/SS_RCPCCSRT/CCSEarlyConfig_up.xml",
                             connection=bb2_local_alias)
        os.remove(download_path_up)

    def _patch_mix_file(self, bb2_local_alias):
        download_path_mix = '/tmp/CCSEarlyConfig_mix.xml'
        self.csn.download_file("/opt/nokia/SS_RCPCCSRT/CCSEarlyConfig_mix.xml",
                               download_path_mix, connection=bb2_local_alias)
        xml_to_edit = self._xml.parse_xml(download_path_mix)
        set_element = self._xml.set_element_text(xml_to_edit, text='4',
                                                 xpath='.//tag[@name="ccs.service.aasyslog.outputmode"]')
        set_element = self._xml.set_element_text(xml_to_edit, text='0',
                                                 xpath='.//tag[@name="ccs.service.aasyslog.linuxsyslog"]')
        set_element = self._xml.set_element_text(xml_to_edit, text='1',
                                                 xpath='.//tag[@name="ccs.service.aasyslog.outputlevel"]')
        set_element = self._xml.set_element_text(xml_to_edit, text='1',
                                                 xpath='.//tag[@name="ccs.service.aasyslog.inputlevel"]')
        self._xml.save_xml(set_element, download_path_mix)
        self.csn.upload_file(download_path_mix,
                             '/opt/nokia/SS_RCPCCSRT/CCSEarlyConfig_mix.xml',
                             connection=bb2_local_alias)
        os.remove(download_path_mix)
